        row_input = input_grid[r]
        left_side = row_input[:5]

        if 1 <= r <= 3:
            color = 4
        elif 5 <= r <= 7:
            color = 3
        elif 9 <= r <= 11:
            color = 7
        elif 13 <= r <= 15:
            color = 2
        else:
            color = 0

        left_filled = [color if c == 0 else c for c in left_side]
        output_grid.append(left_filled + row_input[6:])

# Write final submission
